import{_ as a,o as s,c as n,a3 as l}from"./chunks/framework.bvEHUNtb.js";const c=JSON.parse('{"title":"15 历法体系","description":"从朔望月、回归年、置闰与节气理解中国阴阳合历的结构。","frontmatter":{"title":"15 历法体系","description":"从朔望月、回归年、置闰与节气理解中国阴阳合历的结构。","category":"guide","aliases":["历法体系","农历","阴阳合历"]},"headers":[],"relativePath":"topics/traditional-wisdom/time/calendar-system/index.md","filePath":"topics/traditional-wisdom/time/calendar-system/index.md","lastUpdated":1786982540000}'),e={name:"topics/traditional-wisdom/time/calendar-system/index.md"};function p(i,t,o,d,r,g){return s(),n("div",null,[...t[0]||(t[0]=[l(`<h1 id="_15-·-历法体系-天地的时间契约" tabindex="-1">15 · 历法体系：天地的时间契约 <a class="header-anchor" href="#_15-·-历法体系-天地的时间契约" aria-label="Permalink to &quot;15 · 历法体系：天地的时间契约&quot;">​</a></h1><blockquote><p>二十四节气：天地的时间刻度（已完成）<br> ↓<br><strong>历法体系：如何把天文周期变成人用的日历</strong> ←── 本篇<br> ↓<br> 十二长生 · 五行旺相休囚死</p></blockquote><h2 id="版本与引用说明" tabindex="-1">版本与引用说明 <a class="header-anchor" href="#版本与引用说明" aria-label="Permalink to &quot;版本与引用说明&quot;">​</a></h2><p>本篇主要依据：</p><ul><li>《史记·历书》（司马迁，约前91年）——历法沿革的最早系统记载</li><li>《汉书·律历志》（班固，约公元80年）——历法制度化的权威文献</li><li>《淮南子·天文训》（刘安等，约前139年）——朔望、节气、历法原理的综合记载</li><li>《周髀算经》（成书约前1世纪）——回归年测算的天文依据</li><li>《尚书·尧典》（先秦，今文尚书）——&quot;历象日月星辰，敬授人时&quot;，最早的授时记载</li><li>《礼记·月令》（先秦至汉）——月建与历法的礼制化文献</li><li>《后汉书·律历志》（范晔，5世纪）——历代历法改革的记载</li><li>考古参照：甲骨文干支纪日记录（商代，约前14-前11世纪）——现存最早的干支历法实物</li></ul><hr><h2 id="一、体系定位-在知识树中的坐标" tabindex="-1">一、体系定位：在知识树中的坐标 <a class="header-anchor" href="#一、体系定位-在知识树中的坐标" aria-label="Permalink to &quot;一、体系定位：在知识树中的坐标&quot;">​</a></h2><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>太阳运动（回归年）</span></span>
<span class="line"><span>        +</span></span>
<span class="line"><span>月亮运动（朔望月）</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   如何协调两者？</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>   历法体系                    ←── 本篇</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>┌───────────────────────────────┐</span></span>
<span class="line"><span>│  节气（太阳历骨架）            │</span></span>
<span class="line"><span>│  农历月（朔望月肉身）          │</span></span>
<span class="line"><span>│  置闰（协调机制）              │</span></span>
<span class="line"><span>│  月建（地支月与农历月的关系）  │</span></span>
<span class="line"><span>└───────────────────────────────┘</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>四柱起月柱 · 奇门起局 · 六爻月建 · 择日</span></span></code></pre></div><p><strong>历法在整个体系里的位置：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">层级</th><th style="text-align:left;">内容</th><th style="text-align:left;">本篇关系</th></tr></thead><tbody><tr><td style="text-align:left;">天文层</td><td style="text-align:left;">太阳·月亮·地球的运动周期</td><td style="text-align:left;">历法的物理基础</td></tr><tr><td style="text-align:left;">历法层</td><td style="text-align:left;">如何把天文周期转化为人用的日历</td><td style="text-align:left;">本篇核心</td></tr><tr><td style="text-align:left;">术数层</td><td style="text-align:left;">四柱·奇门·六爻用哪种历</td><td style="text-align:left;">历法的术数接口</td></tr><tr><td style="text-align:left;">文化层</td><td style="text-align:left;">年节·岁时·农耕节律</td><td style="text-align:left;">历法活在日常生活里</td></tr></tbody></table><p><strong>一句话定位：</strong><br> 历法，是人类把天文周期转化为社会时间坐标的系统工程。<br> 中国农历，是世界上现存最复杂、也最精妙的历法体系——<br> 它不是&quot;阴历&quot;，而是一套<strong>阴阳合历</strong>，<br> 同时追踪太阳（节气）和月亮（朔望月），并用置闰法协调两者。</p><h2 id="二、原典依据" tabindex="-1">二、原典依据 <a class="header-anchor" href="#二、原典依据" aria-label="Permalink to &quot;二、原典依据&quot;">​</a></h2><h3 id="文献一-《尚书·尧典》——最早的授时记载" tabindex="-1">文献一：《尚书·尧典》——最早的授时记载 <a class="header-anchor" href="#文献一-《尚书·尧典》——最早的授时记载" aria-label="Permalink to &quot;文献一：《尚书·尧典》——最早的授时记载&quot;">​</a></h3><p><strong>【原典】</strong>《尚书》·虞书·尧典（先秦，今文尚书）</p><p><strong>【原文节选】</strong></p><blockquote><p>乃命羲和，钦若昊天，历象日月星辰，敬授人时。<br> ……期三百有六旬有六日，以闰月定四时成岁。</p></blockquote><p><strong>【解读】</strong><br> 这是中国文献中最早明确记载历法制度的文字。<br> &quot;历象日月星辰，敬授人时&quot;——观测天象，向人民颁布时间，<br> 这是历法最原始的政治功能：<strong>授时，是天子的权力与责任。</strong><br> &quot;以闰月定四时成岁&quot;——用置闰月来协调年与月的关系，<br> 说明至迟在《尚书》成书时，<strong>置闰法已经是历法的核心机制。</strong></p><h3 id="文献二-《史记·历书》——历法沿革的系统记载" tabindex="-1">文献二：《史记·历书》——历法沿革的系统记载 <a class="header-anchor" href="#文献二-《史记·历书》——历法沿革的系统记载" aria-label="Permalink to &quot;文献二：《史记·历书》——历法沿革的系统记载&quot;">​</a></h3><p><strong>【原典】</strong>《史记》卷二十六·历书（司马迁，约前91年）</p><p><strong>【原文节选】</strong></p><blockquote><p>王者易姓受命，必慎始初，改正朔，易服色，推本天元，顺承厥意。</p></blockquote><p><strong>【解读】</strong><br> 司马迁揭示了中国历法的一个重要政治逻辑：<strong>改朝换代，必须改历法。</strong><br> &quot;改正朔&quot;——改变一年的起点（正月）和每月的起点（朔日），是新王朝宣示天命的核心仪式之一。<br> 这解释了为什么中国历史上有那么多套历法——每个朝代都需要&quot;自己的&quot;历法来确立合法性。</p><h3 id="文献三-《汉书·律历志》——历法制度化的权威文献" tabindex="-1">文献三：《汉书·律历志》——历法制度化的权威文献 <a class="header-anchor" href="#文献三-《汉书·律历志》——历法制度化的权威文献" aria-label="Permalink to &quot;文献三：《汉书·律历志》——历法制度化的权威文献&quot;">​</a></h3><p><strong>【原典】</strong>《汉书》卷二十一·律历志（班固，约公元80年）</p><p><strong>【原文节选】</strong></p><blockquote><p>历数之起上矣。传述颛顼命南正重司天以属神，<br> 北正黎司地以属民……<br> 太极元气，函三为一。极，中也。元，始也。<br> 行于十二辰，始动而建子……</p></blockquote><p><strong>【解读】</strong><br> 《律历志》是汉代历法理论的集大成文献，记载了从上古到汉代的历法演变，并系统阐述了<strong>干支纪时、朔望月、回归年</strong>的理论基础。<br> &quot;行于十二辰，始动而建子&quot;——十二地支与历法月建的对应关系，在此有明确记载。</p><h3 id="文献四-《淮南子·天文训》——历法原理的综合阐述" tabindex="-1">文献四：《淮南子·天文训》——历法原理的综合阐述 <a class="header-anchor" href="#文献四-《淮南子·天文训》——历法原理的综合阐述" aria-label="Permalink to &quot;文献四：《淮南子·天文训》——历法原理的综合阐述&quot;">​</a></h3><p><strong>【原典】</strong>《淮南子》卷三·天文训（刘安等，约前139年）</p><p><strong>【原文节选】</strong></p><blockquote><p>日行一度，以周于天。<br> 日冬至，日出东南维，入西南维…… 十九岁为一章。</p></blockquote><p><strong>【解读】</strong><br> &quot;十九岁为一章&quot;—— 19个太阳年 ≈ 235个朔望月，这是阴阳合历置闰的天文基础。</p><blockquote><p>值得注意的是，【<strong>存疑</strong>】古希腊天文学家默冬（Meton）约于前432年发现此周期，而中国文献的记载时间与之相近。</p><p>天文需要大量实际观察数据，需要时间来验证，这是<strong>几代人、几百年积累</strong>的结果，不可能由个人发现，后面单独写了一篇提出假设与质疑，感兴趣可移步。</p></blockquote><h2 id="三、三种历法的本质区别" tabindex="-1">三、三种历法的本质区别 <a class="header-anchor" href="#三、三种历法的本质区别" aria-label="Permalink to &quot;三、三种历法的本质区别&quot;">​</a></h2><p>理解中国历法，必须先厘清三个概念：</p><h3 id="_3-1-纯阴历-太阴历-——以月亮为基准" tabindex="-1">3.1 纯阴历（太阴历）——以月亮为基准 <a class="header-anchor" href="#_3-1-纯阴历-太阴历-——以月亮为基准" aria-label="Permalink to &quot;3.1 纯阴历（太阴历）——以月亮为基准&quot;">​</a></h3><p><strong>定义：</strong> 完全以月亮的朔望周期为基础制定的历法。</p><p><strong>核心参数：</strong></p><ul><li>朔望月 = 29.53059天（月亮从新月到下一个新月）</li><li>一年 = 12个朔望月 = 354.367天</li></ul><p><strong>特点：</strong></p><ul><li>月份与月相严格对应（初一必是新月，十五前后必是满月）</li><li>与太阳年不同步，每年比太阳年少约11天</li><li>季节在历法中漂移，33年后完全错位</li></ul><p><strong>代表：</strong> 伊斯兰历（回历）——现今世界上仍在使用的纯阴历</p><blockquote><p>⚠️ <strong>关键纠正：中国农历不是纯阴历。</strong><br> 这是最常见的误解。中国农历是<strong>阴阳合历</strong>（见3.3节）。</p></blockquote><h3 id="_3-2-纯阳历-太阳历-——以太阳为基准" tabindex="-1">3.2 纯阳历（太阳历）——以太阳为基准 <a class="header-anchor" href="#_3-2-纯阳历-太阳历-——以太阳为基准" aria-label="Permalink to &quot;3.2 纯阳历（太阳历）——以太阳为基准&quot;">​</a></h3><p><strong>定义：</strong> 完全以地球绕太阳公转周期（回归年）为基础制定的历法。</p><p><strong>核心参数：</strong></p><ul><li>回归年 = 365.2422天</li><li>现行公历（格里历）：平年365天，闰年366天</li></ul><p><strong>特点：</strong></p><ul><li>与季节严格同步（春分永远在3月20-21日前后）</li><li>月份是人为规定，与月相无关</li><li>节气在公历中日期几乎固定（误差1-2天）</li></ul><p><strong>代表：</strong> 格里历（公历）——现今世界通用</p><p><strong>中国的太阳历传统：</strong><br> 二十四节气，本质上就是一套<strong>纯太阳历</strong>，它是中国古代独立发展的太阳历坐标系，与格里历的天文基础完全相同，只是分段方式不同。</p><h3 id="_3-3-阴阳合历——中国农历的真相" tabindex="-1">3.3 阴阳合历——中国农历的真相 <a class="header-anchor" href="#_3-3-阴阳合历——中国农历的真相" aria-label="Permalink to &quot;3.3 阴阳合历——中国农历的真相&quot;">​</a></h3><p><strong>定义：</strong> 同时以月亮周期和太阳周期为基础，用置闰法协调两者的历法。</p><p><strong>中国农历的双轨结构：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>中国农历（阴阳合历）</span></span>
<span class="line"><span>    ├── 阴历轨道：朔望月（月份 = 月亮周期）</span></span>
<span class="line"><span>    │       初一 = 朔日（新月）</span></span>
<span class="line"><span>    │       十五/十六 = 望日（满月）</span></span>
<span class="line"><span>    │       每月29或30天</span></span>
<span class="line"><span>    │</span></span>
<span class="line"><span>    └── 阳历轨道：节气（年 = 太阳周期）</span></span>
<span class="line"><span>            二十四节气嵌入农历</span></span>
<span class="line"><span>            节气日期在农历中每年漂移</span></span>
<span class="line"><span>            但在公历中几乎固定</span></span></code></pre></div><p><strong>协调机制：置闰法</strong></p><ul><li>问题：12个朔望月（354天）比回归年（365天）少约11天</li><li>解决：每隔2-3年插入一个<strong>闰月</strong>，补足差额</li><li>规则：19年插入7个闰月（默冬周期）</li><li>判断：<strong>无中气月为闰月</strong>（详见6.3节）</li></ul><p><strong>农历的精妙之处：</strong><br> 它同时满足了两个需求——</p><ul><li>月相可见（农业灌溉、潮汐、渔业需要月相）</li><li>季节准确（农耕播种需要节气/太阳位置）</li></ul><h3 id="_3-4-三种历法对比总览" tabindex="-1">3.4 三种历法对比总览 <a class="header-anchor" href="#_3-4-三种历法对比总览" aria-label="Permalink to &quot;3.4 三种历法对比总览&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">维度</th><th style="text-align:left;">纯阴历（伊斯兰历）</th><th style="text-align:left;">纯阳历（公历）</th><th style="text-align:left;">阴阳合历（中国农历）</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>月份基准</strong></td><td style="text-align:left;">朔望月</td><td style="text-align:left;">人为规定</td><td style="text-align:left;">朔望月</td></tr><tr><td style="text-align:left;"><strong>年的基准</strong></td><td style="text-align:left;">12朔望月（354天）</td><td style="text-align:left;">回归年（365天）</td><td style="text-align:left;">回归年（含置闰）</td></tr><tr><td style="text-align:left;"><strong>月相对应</strong></td><td style="text-align:left;">✅ 严格对应</td><td style="text-align:left;">❌ 无关</td><td style="text-align:left;">✅ 严格对应</td></tr><tr><td style="text-align:left;"><strong>季节对应</strong></td><td style="text-align:left;">❌ 漂移</td><td style="text-align:left;">✅ 固定</td><td style="text-align:left;">✅ 通过节气固定</td></tr><tr><td style="text-align:left;"><strong>置闰机制</strong></td><td style="text-align:left;">❌ 无</td><td style="text-align:left;">闰日（2月29日）</td><td style="text-align:left;">闰月（19年7闰）</td></tr><tr><td style="text-align:left;"><strong>复杂程度</strong></td><td style="text-align:left;">低</td><td style="text-align:left;">低</td><td style="text-align:left;">高</td></tr></tbody></table><h2 id="四、中国历法的演变史" tabindex="-1">四、中国历法的演变史 <a class="header-anchor" href="#四、中国历法的演变史" aria-label="Permalink to &quot;四、中国历法的演变史&quot;">​</a></h2><h3 id="_4-1-上古-物候历与观象授时-前有文字记载之前" tabindex="-1">4.1 上古：物候历与观象授时（前有文字记载之前） <a class="header-anchor" href="#_4-1-上古-物候历与观象授时-前有文字记载之前" aria-label="Permalink to &quot;4.1 上古：物候历与观象授时（前有文字记载之前）&quot;">​</a></h3><p>最早的&quot;历法&quot;，不是数字，而是<strong>自然现象的观察</strong>：</p><ul><li>候鸟迁徙（大雁北归 = 春天来了）</li><li>植物物候（桃花开 = 可以播种了）</li><li>星象观测（昴星团晨见 = 秋收时节）</li></ul><p>这就是《夏小正》记载的<strong>物候历</strong>传统——用动植物的季节性变化来标记时间，是一切历法的原始形态。</p><p><strong>观象授时的政治化：</strong><br> 《尚书·尧典》记载，尧命羲和&quot;历象日月星辰，敬授人时&quot;，说明至迟在传说中的尧舜时代，<strong>天文观测已经是国家行为</strong>，授时权力掌握在天子手中。</p><h3 id="_4-2-商代-甲骨文中的干支纪日-约前14-前11世纪" tabindex="-1">4.2 商代：甲骨文中的干支纪日（约前14-前11世纪） <a class="header-anchor" href="#_4-2-商代-甲骨文中的干支纪日-约前14-前11世纪" aria-label="Permalink to &quot;4.2 商代：甲骨文中的干支纪日（约前14-前11世纪）&quot;">​</a></h3><p><strong>考古证据：</strong><br> 殷墟出土的甲骨文中，有大量干支纪日记录，<br> 这是目前可考的<strong>最早的系统性历法实物</strong>。</p><p><strong>商代历法特征：</strong></p><ul><li>已使用干支纪日（六十甲子循环）</li><li>已有朔望月的概念（&quot;月&quot;字的甲骨文象形即为月牙）</li><li>已有置闰的实践（甲骨文中有&quot;十三月&quot;的记载）</li><li>岁首建丑（以丑月为正月）——后世&quot;夏历建寅、殷历建丑、周历建子&quot;之说的来源</li></ul><p><strong>意义：</strong><br> 商代甲骨文证明，中国历法的核心要素（干支纪日、朔望月、置闰）在距今3000年以上已经完备。</p><h3 id="_4-3-周代-四分历的形成-约前8-前3世纪" tabindex="-1">4.3 周代：四分历的形成（约前8-前3世纪） <a class="header-anchor" href="#_4-3-周代-四分历的形成-约前8-前3世纪" aria-label="Permalink to &quot;4.3 周代：四分历的形成（约前8-前3世纪）&quot;">​</a></h3><p><strong>四分历的核心参数：</strong></p><ul><li>回归年 = 365又1/4天（即365.25天）</li><li>朔望月 = 29又499/940天（≈29.53085天）</li><li>19年7闰</li></ul><p>&quot;四分历&quot;得名于将回归年定为365<strong>又四分之一</strong>天。</p><p><strong>先秦各国历法：</strong><br> 战国时期，各诸侯国使用不同的历法，岁首各异（有建子、建丑、建寅之别），这是&quot;战国七雄&quot;时代历法混乱的历史背景。</p><p><strong>《左传》《国语》中的历法记载：</strong><br> 先秦文献中大量出现&quot;某年某月某日&quot;的干支纪日，证明四分历在春秋战国时期已广泛使用。</p><h3 id="_4-4-秦汉-颛顼历→太初历-历法史的里程碑" tabindex="-1">4.4 秦汉：颛顼历→太初历（历法史的里程碑） <a class="header-anchor" href="#_4-4-秦汉-颛顼历→太初历-历法史的里程碑" aria-label="Permalink to &quot;4.4 秦汉：颛顼历→太初历（历法史的里程碑）&quot;">​</a></h3><p><strong>秦·颛顼历（前221年-前104年）：</strong></p><ul><li>秦始皇统一六国后，颁布颛顼历</li><li>岁首建亥（以亥月/十月为正月）</li><li>这是&quot;秦以十月为岁首&quot;的来源</li><li>颛顼历是四分历的一种，精度有限</li></ul><p><strong>汉武帝·太初历（前104年）：</strong><br> 这是中国历法史上最重要的改革节点。</p><table tabindex="0"><thead><tr><th style="text-align:left;">改革内容</th><th style="text-align:left;">颛顼历（旧）</th><th style="text-align:left;">太初历（新）</th></tr></thead><tbody><tr><td style="text-align:left;">岁首</td><td style="text-align:left;">建亥（十月）</td><td style="text-align:left;"><strong>建寅（正月）</strong></td></tr><tr><td style="text-align:left;">节气</td><td style="text-align:left;">未正式入历</td><td style="text-align:left;"><strong>二十四节气正式入历</strong></td></tr><tr><td style="text-align:left;">置闰规则</td><td style="text-align:left;">粗略</td><td style="text-align:left;"><strong>无中气置闰（精确化）</strong></td></tr><tr><td style="text-align:left;">历法基准</td><td style="text-align:left;">纯四分历</td><td style="text-align:left;">阴阳合历完整体系</td></tr></tbody></table><p><strong>太初历的历史意义：</strong></p><ol><li>将岁首定为建寅（正月/寅月），沿用至今</li><li>将二十四节气正式纳入国家历法</li><li>确立&quot;无中气置闰&quot;规则，解决了置闰的精确判断问题</li><li>奠定了此后2000年中国历法的基本框架</li></ol><blockquote><p>司马迁参与了太初历的制定工作，《史记·历书》是这次历法改革的第一手文献记录。</p></blockquote><h3 id="_4-5-历代历法改革简表" tabindex="-1">4.5 历代历法改革简表 <a class="header-anchor" href="#_4-5-历代历法改革简表" aria-label="Permalink to &quot;4.5 历代历法改革简表&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">朝代</th><th style="text-align:left;">历法名称</th><th style="text-align:left;">时间</th><th style="text-align:left;">主要贡献</th></tr></thead><tbody><tr><td style="text-align:left;">秦</td><td style="text-align:left;">颛顼历</td><td style="text-align:left;">前221年</td><td style="text-align:left;">统一六国历法</td></tr><tr><td style="text-align:left;">西汉</td><td style="text-align:left;"><strong>太初历</strong></td><td style="text-align:left;"><strong>前104年</strong></td><td style="text-align:left;"><strong>里程碑：节气入历，建寅岁首</strong></td></tr><tr><td style="text-align:left;">东汉</td><td style="text-align:left;">四分历</td><td style="text-align:left;">85年</td><td style="text-align:left;">修正太初历误差</td></tr><tr><td style="text-align:left;">三国·魏</td><td style="text-align:left;">景初历</td><td style="text-align:left;">237年</td><td style="text-align:left;">改进朔望计算</td></tr><tr><td style="text-align:left;">南北朝</td><td style="text-align:left;">大明历</td><td style="text-align:left;">463年</td><td style="text-align:left;">祖冲之，引入岁差概念</td></tr><tr><td style="text-align:left;">隋</td><td style="text-align:left;">皇极历</td><td style="text-align:left;">604年</td><td style="text-align:left;">刘焯，不等间距插值法</td></tr><tr><td style="text-align:left;">唐</td><td style="text-align:left;">大衍历</td><td style="text-align:left;">728年</td><td style="text-align:left;">僧一行，实测子午线长度</td></tr><tr><td style="text-align:left;">元</td><td style="text-align:left;"><strong>授时历</strong></td><td style="text-align:left;"><strong>1281年</strong></td><td style="text-align:left;"><strong>郭守敬，回归年=365.2425天，与格里历同精度，早301年</strong></td></tr><tr><td style="text-align:left;">明</td><td style="text-align:left;">大统历</td><td style="text-align:left;">1384年</td><td style="text-align:left;">基本沿用授时历</td></tr><tr><td style="text-align:left;">清</td><td style="text-align:left;">时宪历</td><td style="text-align:left;">1645年</td><td style="text-align:left;">引入西方天文学，汤若望参与</td></tr><tr><td style="text-align:left;">现代</td><td style="text-align:left;">紫金历</td><td style="text-align:left;">1929年至今</td><td style="text-align:left;">现行农历的计算基础</td></tr></tbody></table><p><strong>特别说明——授时历 vs 格里历：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">授时历（元·1281年）</th><th style="text-align:left;">格里历（西方·1582年）</th></tr></thead><tbody><tr><td style="text-align:left;">回归年长度</td><td style="text-align:left;"><strong>365.2425天</strong></td><td style="text-align:left;"><strong>365.2425天</strong></td></tr><tr><td style="text-align:left;">精度</td><td style="text-align:left;">与现代测量值误差26秒</td><td style="text-align:left;">与现代测量值误差26秒</td></tr><tr><td style="text-align:left;">时间</td><td style="text-align:left;"><strong>早301年</strong></td><td style="text-align:left;">—</td></tr></tbody></table><p>郭守敬在1281年得出的回归年数值，与300年后西方颁布的格里历完全相同。这不是巧合，而是中国天文学长期积累的结果。</p><h2 id="五、农历的核心机制" tabindex="-1">五、农历的核心机制 <a class="header-anchor" href="#五、农历的核心机制" aria-label="Permalink to &quot;五、农历的核心机制&quot;">​</a></h2><h3 id="_5-1-朔望月-月份的物理基础" tabindex="-1">5.1 朔望月：月份的物理基础 <a class="header-anchor" href="#_5-1-朔望月-月份的物理基础" aria-label="Permalink to &quot;5.1 朔望月：月份的物理基础&quot;">​</a></h3><p><strong>朔望月 = 29.53059天</strong></p><p>月亮的四个关键相位：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>朔（新月）→ 上弦月 → 望（满月）→ 下弦月 → 朔（新月）</span></span>
<span class="line"><span>  初一        初七/八    十五/十六    二十二/三    下月初一</span></span></code></pre></div><p><strong>农历月份的规则：</strong></p><ul><li>每月以<strong>朔日</strong>（新月）为初一</li><li>大月 = 30天，小月 = 29天</li><li>大小月的安排由精确天文计算决定（不是固定交替）</li><li>现行农历：用现代天文方法精确计算每月朔日时刻</li></ul><p><strong>为什么初一不一定能看到月亮？</strong><br> 朔日是月亮与太阳同方向的时刻（合朔），<br> 月亮完全被太阳光淹没，肉眼不可见。<br> 初二初三才能看到细细的月牙。</p><hr><h3 id="_5-2-回归年-年的天文基础" tabindex="-1">5.2 回归年：年的天文基础 <a class="header-anchor" href="#_5-2-回归年-年的天文基础" aria-label="Permalink to &quot;5.2 回归年：年的天文基础&quot;">​</a></h3><p><strong>回归年 = 365.2422天</strong></p><p>这是地球绕太阳公转一周（从春分点到下一个春分点）的时间。</p><p><strong>农历年的长度：</strong></p><ul><li>平年 = 12个朔望月 = 354或355天</li><li>闰年 = 13个朔望月 = 383或384天</li><li>平均年长 ≈ 365.25天（通过19年7闰实现）</li></ul><p><strong>与公历年的比较：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;"></th><th style="text-align:left;">农历平年</th><th style="text-align:left;">农历闰年</th><th style="text-align:left;">公历平年</th><th style="text-align:left;">公历闰年</th></tr></thead><tbody><tr><td style="text-align:left;">天数</td><td style="text-align:left;">354/355天</td><td style="text-align:left;">383/384天</td><td style="text-align:left;">365天</td><td style="text-align:left;">366天</td></tr><tr><td style="text-align:left;">月数</td><td style="text-align:left;">12个月</td><td style="text-align:left;">13个月</td><td style="text-align:left;">12个月</td><td style="text-align:left;">12个月</td></tr></tbody></table><hr><h3 id="_5-3-置闰法-协调阴阳的核心机制" tabindex="-1">5.3 置闰法：协调阴阳的核心机制 <a class="header-anchor" href="#_5-3-置闰法-协调阴阳的核心机制" aria-label="Permalink to &quot;5.3 置闰法：协调阴阳的核心机制&quot;">​</a></h3><p><strong>问题的本质：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>12个朔望月 = 354.367天</span></span>
<span class="line"><span>1个回归年  = 365.2422天</span></span>
<span class="line"><span>差值       = 10.875天/年</span></span></code></pre></div><p>如果不置闰，每年农历比太阳年少约11天，<br> 3年后少33天（超过一个月），<br> 17年后，农历的&quot;正月&quot;会出现在夏天——<br> 历法与季节完全脱节。</p><p><strong>解决方案：19年7闰</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>19个回归年 = 19 × 365.2422 = 6939.6018天</span></span>
<span class="line"><span>235个朔望月 = 235 × 29.53059 = 6939.6887天</span></span>
<span class="line"><span>误差 = 0.0869天（约2小时）</span></span></code></pre></div><p>19个太阳年与235个朔望月几乎完全相等，<br> 因此每19年插入7个闰月，可以使阴阳历保持同步。</p><p><strong>无中气置闰：判断哪个月是闰月</strong></p><p>这是太初历确立的精确置闰规则：</p><p><strong>在一个含有13个月的农历年中，第一个没有&quot;中气&quot;的月份，定为闰月。</strong></p><hr><p><strong>什么是&quot;中气&quot;？</strong><br> 二十四节气分为12个&quot;节&quot;和12个&quot;气&quot;（中气）：</p><ul><li>节：立春、惊蛰、清明、立夏、芒种、小暑、立秋、白露、寒露、立冬、大雪、小寒</li><li>气（中气）：雨水、春分、谷雨、小满、夏至、大暑、处暑、秋分、霜降、小雪、冬至、大寒</li></ul><p><strong>为什么用&quot;无中气&quot;判断闰月？</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>中气间隔 = 回归年 ÷ 12 ≈ 30.44天</span></span>
<span class="line"><span>朔望月   = 29.53天</span></span></code></pre></div><p>中气间隔（30.44天）&gt; 朔望月（29.53天），<br> 因此偶尔会出现某个农历月内没有中气的情况——<br> 这个月就是&quot;多出来&quot;的月份，定为闰月。</p><p><strong>实例：2020年闰四月</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>2020年农历：</span></span>
<span class="line"><span>正月（含雨水）→ 二月（含春分）→ 三月（含谷雨）→ 四月（含小满）</span></span>
<span class="line"><span>→ 闰四月（无中气！）→ 五月（含夏至）→ ……</span></span></code></pre></div><p>闰四月内没有任何中气（小满在四月，夏至在五月），<br> 因此这个月被定为&quot;闰四月&quot;。</p><h3 id="_5-4-月建-地支月与农历月的关系" tabindex="-1">5.4 月建：地支月与农历月的关系 <a class="header-anchor" href="#_5-4-月建-地支月与农历月的关系" aria-label="Permalink to &quot;5.4 月建：地支月与农历月的关系&quot;">​</a></h3><p><strong>月建</strong>，是地支月（干支历的月份）与历法的接口。</p><p><strong>核心规则：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>月建 = 以节气为换月基准的地支月</span></span>
<span class="line"><span>     ≠ 农历朔望月</span></span></code></pre></div><p><strong>十二月建对照表：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">地支月</th><th style="text-align:left;">月建</th><th style="text-align:left;">对应节气（节）</th><th style="text-align:left;">公历约日期</th></tr></thead><tbody><tr><td style="text-align:left;">寅月</td><td style="text-align:left;">建寅</td><td style="text-align:left;">立春</td><td style="text-align:left;">约2月4日</td></tr><tr><td style="text-align:left;">卯月</td><td style="text-align:left;">建卯</td><td style="text-align:left;">惊蛰</td><td style="text-align:left;">约3月6日</td></tr><tr><td style="text-align:left;">辰月</td><td style="text-align:left;">建辰</td><td style="text-align:left;">清明</td><td style="text-align:left;">约4月5日</td></tr><tr><td style="text-align:left;">巳月</td><td style="text-align:left;">建巳</td><td style="text-align:left;">立夏</td><td style="text-align:left;">约5月6日</td></tr><tr><td style="text-align:left;">午月</td><td style="text-align:left;">建午</td><td style="text-align:left;">芒种</td><td style="text-align:left;">约6月6日</td></tr><tr><td style="text-align:left;">未月</td><td style="text-align:left;">建未</td><td style="text-align:left;">小暑</td><td style="text-align:left;">约7月7日</td></tr><tr><td style="text-align:left;">申月</td><td style="text-align:left;">建申</td><td style="text-align:left;">立秋</td><td style="text-align:left;">约8月7日</td></tr><tr><td style="text-align:left;">酉月</td><td style="text-align:left;">建酉</td><td style="text-align:left;">白露</td><td style="text-align:left;">约9月8日</td></tr><tr><td style="text-align:left;">戌月</td><td style="text-align:left;">建戌</td><td style="text-align:left;">寒露</td><td style="text-align:left;">约10月8日</td></tr><tr><td style="text-align:left;">亥月</td><td style="text-align:left;">建亥</td><td style="text-align:left;">立冬</td><td style="text-align:left;">约11月7日</td></tr><tr><td style="text-align:left;">子月</td><td style="text-align:left;">建子</td><td style="text-align:left;">大雪</td><td style="text-align:left;">约12月7日</td></tr><tr><td style="text-align:left;">丑月</td><td style="text-align:left;">建丑</td><td style="text-align:left;">小寒</td><td style="text-align:left;">约1月6日</td></tr></tbody></table><p><strong>月建 vs 农历月：两套系统并行</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>月建（地支月）：以节气交节为换月时刻，纯太阳历</span></span>
<span class="line"><span>农历月：       以朔日（新月）为初一，朔望月</span></span>
<span class="line"><span></span></span>
<span class="line"><span>两者不同步：</span></span>
<span class="line"><span>例：2026年2月</span></span>
<span class="line"><span>  农历：正月（从2月17日朔日开始）</span></span>
<span class="line"><span>  月建：丑月（1月6日小寒→2月4日立春）</span></span>
<span class="line"><span>       寅月（2月4日立春→3月6日惊蛰）</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  2月4日立春之前出生 → 月建丑月</span></span>
<span class="line"><span>  2月4日立春之后出生 → 月建寅月</span></span>
<span class="line"><span>  无论农历是几月，月建以节气为准。</span></span></code></pre></div><h3 id="_5-5-岁首之争-建寅-vs-建子-vs-建亥" tabindex="-1">5.5 岁首之争：建寅 vs 建子 vs 建亥 <a class="header-anchor" href="#_5-5-岁首之争-建寅-vs-建子-vs-建亥" aria-label="Permalink to &quot;5.5 岁首之争：建寅 vs 建子 vs 建亥&quot;">​</a></h3><p><strong>岁首</strong>，即一年的起点，是历法的政治核心。</p><p>中国历史上有三种主要的岁首：</p><table tabindex="0"><thead><tr><th style="text-align:left;">岁首</th><th style="text-align:left;">正月</th><th style="text-align:left;">使用朝代</th><th style="text-align:left;">依据</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>建寅</strong></td><td style="text-align:left;">寅月（立春后）</td><td style="text-align:left;">夏·汉（太初历后）·至今</td><td style="text-align:left;">&quot;人统&quot;，以人事为中心</td></tr><tr><td style="text-align:left;"><strong>建丑</strong></td><td style="text-align:left;">丑月（小寒后）</td><td style="text-align:left;">商</td><td style="text-align:left;">&quot;地统&quot;，以大地为中心</td></tr><tr><td style="text-align:left;"><strong>建子</strong></td><td style="text-align:left;">子月（大雪后）</td><td style="text-align:left;">周·秦（颛顼历前）</td><td style="text-align:left;">&quot;天统&quot;，以天道为中心</td></tr><tr><td style="text-align:left;"><strong>建亥</strong></td><td style="text-align:left;">亥月（立冬后）</td><td style="text-align:left;">秦（颛顼历）</td><td style="text-align:left;">秦以水德，亥为水旺</td></tr></tbody></table><p><strong>&quot;三正论&quot;：</strong><br> 《史记·历书》记载，夏用建寅、商用建丑、周用建子，称为&quot;三正&quot;，历代改朝换代往往在三者之间选择，以示&quot;承天命、继正统&quot;。</p><p><strong>现行农历的岁首：建寅</strong><br> 汉武帝太初历确立建寅为岁首，此后除少数例外，中国历法一直以寅月（立春后的第一个朔日）为正月初一。</p><blockquote><p><strong>注意：术数体系的&quot;年&quot;以立春换年，不以正月初一换年。</strong><br> 农历正月初一是&quot;春节&quot;（民俗年），<br> 立春才是干支历的&quot;年&quot;的换年节点（术数年）。<br> 两者可能相差数天，在四柱排盘时必须区分。</p></blockquote><h2 id="六、节气在历法中的位置" tabindex="-1">六、节气在历法中的位置 <a class="header-anchor" href="#六、节气在历法中的位置" aria-label="Permalink to &quot;六、节气在历法中的位置&quot;">​</a></h2><h3 id="_6-1-节气是农历的-阳骨架" tabindex="-1">6.1 节气是农历的&quot;阳骨架&quot; <a class="header-anchor" href="#_6-1-节气是农历的-阳骨架" aria-label="Permalink to &quot;6.1 节气是农历的&quot;阳骨架&quot;&quot;">​</a></h3><p>一个最精准的比喻：</p><p>农历 = 骨架 + 肉身</p><p>骨架 = 二十四节气（太阳历，固定不动）</p><p>肉身 = 朔望月（阴历，随月亮浮动）</p><p>节气是农历的<strong>太阳坐标</strong>，<br> 朔望月是农历的<strong>月亮坐标</strong>，<br> 两者叠加，构成阴阳合历。</p><h4 id="为什么节气在公历中日期几乎固定" tabindex="-1">为什么节气在公历中日期几乎固定？ <a class="header-anchor" href="#为什么节气在公历中日期几乎固定" aria-label="Permalink to &quot;为什么节气在公历中日期几乎固定？&quot;">​</a></h4><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>节气 = 太阳到达某黄经度数的时刻</span></span>
<span class="line"><span>公历 = 也是太阳历（回归年为基准）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 两者天文基础相同</span></span>
<span class="line"><span>→ 节气在公历中日期误差仅1-2天</span></span></code></pre></div><h4 id="为什么节气在农历中日期每年不同" tabindex="-1">为什么节气在农历中日期每年不同？ <a class="header-anchor" href="#为什么节气在农历中日期每年不同" aria-label="Permalink to &quot;为什么节气在农历中日期每年不同？&quot;">​</a></h4><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>农历月 = 朔望月（月亮周期）</span></span>
<span class="line"><span>节气   = 太阳周期</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 两者基准不同</span></span>
<span class="line"><span>→ 节气在农历中每年漂移，无规律可循</span></span></code></pre></div><p><strong>实例对比：冬至</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">年份</th><th style="text-align:left;">公历日期</th><th style="text-align:left;">农历日期</th></tr></thead><tbody><tr><td style="text-align:left;">2023年</td><td style="text-align:left;">12月22日</td><td style="text-align:left;">农历十一月初十</td></tr><tr><td style="text-align:left;">2024年</td><td style="text-align:left;">12月21日</td><td style="text-align:left;">农历十一月廿一</td></tr><tr><td style="text-align:left;">2025年</td><td style="text-align:left;">12月22日</td><td style="text-align:left;">农历十一月初三</td></tr><tr><td style="text-align:left;">2026年</td><td style="text-align:left;">12月22日</td><td style="text-align:left;">农历十一月十四</td></tr></tbody></table><p>公历日期：极度稳定（12月21-23日）<br> 农历日期：每年不同，毫无规律</p><p>这就是节气&quot;属于太阳历&quot;的最直观证明。</p><h3 id="_6-2-无中气置闰-节气决定闰月" tabindex="-1">6.2 无中气置闰：节气决定闰月 <a class="header-anchor" href="#_6-2-无中气置闰-节气决定闰月" aria-label="Permalink to &quot;6.2 无中气置闰：节气决定闰月&quot;">​</a></h3><p>（已在5.3节详述，此处补充逻辑链）</p><p><strong>完整逻辑链：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>步骤一：确定当年是否需要置闰</span></span>
<span class="line"><span>  → 判断：本农历年是否包含13个朔望月？</span></span>
<span class="line"><span>  → 依据：19年7闰的周期</span></span>
<span class="line"><span></span></span>
<span class="line"><span>步骤二：确定哪个月是闰月</span></span>
<span class="line"><span>  → 规则：找到第一个没有中气的农历月</span></span>
<span class="line"><span>  → 该月即为前一个月的闰月</span></span>
<span class="line"><span></span></span>
<span class="line"><span>步骤三：命名闰月</span></span>
<span class="line"><span>  → 闰月以前一个月命名</span></span>
<span class="line"><span>  → 例：闰四月 = 四月之后、没有中气的那个月</span></span></code></pre></div><p><strong>为什么是&quot;无中气&quot;而非&quot;无节&quot;？</strong></p><p>中气（12个）间隔约30.44天，<br> 节（12个）间隔同样约30.44天，<br> 但中气是每个地支月的&quot;核心标志&quot;——<br> 每个地支月必须包含对应的中气：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>寅月必含雨水，卯月必含春分，辰月必含谷雨 ……</span></span></code></pre></div><p>若某农历月不含中气，说明这个月&quot;没有归属&quot;，是多出来的，因此定为闰月。</p><p>这个规则的精妙之处在于：<br><strong>它用节气（太阳历）来规范朔望月（阴历）的置闰，正是阴阳合历&quot;以阳统阴&quot;的核心体现。</strong></p><h3 id="_6-3-为什么说农历是-世界上最复杂的历法" tabindex="-1">6.3 为什么说农历是&quot;世界上最复杂的历法&quot; <a class="header-anchor" href="#_6-3-为什么说农历是-世界上最复杂的历法" aria-label="Permalink to &quot;6.3 为什么说农历是&quot;世界上最复杂的历法&quot;&quot;">​</a></h3><p><strong>复杂性来源：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 每月天数不固定（29或30天，由精确天文计算决定）</span></span>
<span class="line"><span>② 每年月数不固定（12或13个月）</span></span>
<span class="line"><span>③ 闰月位置不固定（可以是任何月份的闰月）</span></span>
<span class="line"><span>④ 同一年可能出现两个同名月（如两个&quot;四月&quot;）</span></span>
<span class="line"><span>⑤ 节气日期在农历中每年不同</span></span>
<span class="line"><span>⑥ 年的长度在354-384天之间浮动</span></span></code></pre></div><p><strong>精妙性来源：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>① 月相可见：初一必是新月，十五前后必是满月</span></span>
<span class="line"><span>② 季节准确：通过节气，与太阳年严格同步</span></span>
<span class="line"><span>③ 19年自我修正：19年后，月相与节气几乎回到原位</span></span>
<span class="line"><span>④ 农业适用：既能看月相（潮汐·渔业），又能看节气（播种·收割）</span></span></code></pre></div><p><strong>一句话总结：</strong><br> 农历的复杂，是为了同时服务两个主人——太阳和月亮。<br> 它的精妙，在于用一套规则，让两个不同步的天文周期，在19年的尺度上实现近乎完美的和谐。</p><h2 id="七、术数体系与历法的接口" tabindex="-1">七、术数体系与历法的接口 <a class="header-anchor" href="#七、术数体系与历法的接口" aria-label="Permalink to &quot;七、术数体系与历法的接口&quot;">​</a></h2><blockquote><p>对术数不感兴趣可直接跳过。 该章为本篇对于术数应用的实战验证章节。</p></blockquote><p><strong>核心问题：不同术数体系，用的是哪种历？</strong></p><p>答案出乎很多人意料：<strong>不同术数用不同的历法基准。</strong></p><h3 id="_7-1-四柱八字-用节气历-纯太阳历" tabindex="-1">7.1 四柱八字：用节气历（纯太阳历） <a class="header-anchor" href="#_7-1-四柱八字-用节气历-纯太阳历" aria-label="Permalink to &quot;7.1 四柱八字：用节气历（纯太阳历）&quot;">​</a></h3><p><strong>月柱的历法基准：节气</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>换月标准：十二节（立春·惊蛰·清明·立夏·芒种·小暑</span></span>
<span class="line"><span>                   立秋·白露·寒露·立冬·大雪·小寒）</span></span>
<span class="line"><span>换年标准：立春</span></span>
<span class="line"><span></span></span>
<span class="line"><span>与农历月的关系：无关</span></span>
<span class="line"><span>与公历月的关系：无关</span></span>
<span class="line"><span>唯一基准：太阳到达对应黄经度数的精确时刻</span></span></code></pre></div><p><strong>为什么四柱不用农历月？</strong></p><p>四柱的月柱，本质上是<strong>太阳在黄道上的位置</strong>，代表出生时刻的&quot;季节能量&quot;。<br> 季节能量由太阳决定，与月亮无关。<br> 农历月是月亮周期，用农历月排月柱，等于用月亮的位置来代表太阳的能量——逻辑上根本不通。</p><p><strong>实战规则：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>排月柱三步法：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第一步：查出生日期对应的节气区间</span></span>
<span class="line"><span>  → 该日期在哪两个&quot;节&quot;之间？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第二步：确认是否已过节</span></span>
<span class="line"><span>  → 必须查精确交节时刻（精确到分钟）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>第三步：确定月柱</span></span>
<span class="line"><span>  → 过了节 = 新月柱</span></span>
<span class="line"><span>  → 未过节 = 上一个月柱</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：2026年2月10日 08:30出生</span></span>
<span class="line"><span>  立春：2026年2月4日 05:02</span></span>
<span class="line"><span>  惊蛰：2026年3月6日 03:07</span></span>
<span class="line"><span>  → 已过立春，未到惊蛰</span></span>
<span class="line"><span>  → 月柱 = 寅月 ✓</span></span></code></pre></div><p><strong>年柱的历法基准：立春</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>立春前出生 → 用上一年的年干支</span></span>
<span class="line"><span>立春后出生 → 用本年的年干支</span></span>
<span class="line"><span></span></span>
<span class="line"><span>例：2026年2月3日出生（立春前）</span></span>
<span class="line"><span>  → 年柱用乙巳年（2025年干支）</span></span>
<span class="line"><span>  </span></span>
<span class="line"><span>  2026年2月5日出生（立春后）</span></span>
<span class="line"><span>  → 年柱用丙午年（2026年干支）</span></span></code></pre></div><blockquote><p>⚠️ 这与春节（农历正月初一）完全无关。<br> 2026年春节是2月17日，但干支历的换年是2月4日立春。两者相差13天，不可混淆。</p></blockquote><h3 id="_7-2-奇门遁甲-用节气历-最精细的太阳历应用" tabindex="-1">7.2 奇门遁甲：用节气历（最精细的太阳历应用） <a class="header-anchor" href="#_7-2-奇门遁甲-用节气历-最精细的太阳历应用" aria-label="Permalink to &quot;7.2 奇门遁甲：用节气历（最精细的太阳历应用）&quot;">​</a></h3><p><strong>奇门的时间基准：节气 × 三元</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一年 = 24个节气</span></span>
<span class="line"><span>每个节气 = 上元·中元·下元（三元）</span></span>
<span class="line"><span>每元 = 对应一个奇门局</span></span>
<span class="line"><span></span></span>
<span class="line"><span>局的种类：</span></span>
<span class="line"><span>  阳遁 9局（局1-9）  ← 冬至→夏至，阳气渐长</span></span>
<span class="line"><span>  阴遁 9局（局1-9）  ← 夏至→冬至，阴气渐长</span></span>
<span class="line"><span>  共 18局，循环使用</span></span>
<span class="line"><span></span></span>
<span class="line"><span>24节气 × 3元 = 72元/年</span></span>
<span class="line"><span>72元对应的局，从9局中循环取用</span></span></code></pre></div><blockquote><p>⚠️ 注意：局只有9个（阳遁9+阴遁9=18种），<br> 不是72个。72是元的数量，局是循环使用的。</p></blockquote><p><strong>三元的天数：补拆法 vs 置闰法</strong></p><p>三元的天数划分，历史上有两种主要算法：</p><table tabindex="0"><thead><tr><th style="text-align:left;">算法</th><th style="text-align:left;">三元天数</th><th style="text-align:left;">特点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>补拆法</strong></td><td style="text-align:left;">强制每元5天，用补、拆凑整</td><td style="text-align:left;">整齐，便于排盘，民间常用</td></tr><tr><td style="text-align:left;"><strong>置闰法（超神接气）</strong></td><td style="text-align:left;">每元天数不固定，以实际节气时刻为准</td><td style="text-align:left;">精确，但处理复杂，传统正宗</td></tr></tbody></table><p>两种算法各有传承，实践中需按所学门派规范操作。</p><p><strong>换局的精确性</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>奇门换局 = 节气交节的精确时刻</span></span>
<span class="line"><span>         ≠ 当天零点</span></span>
<span class="line"><span>         ≠ 农历初一</span></span>
<span class="line"><span></span></span>
<span class="line"><span>交节前一秒 → 旧局</span></span>
<span class="line"><span>交节后一秒 → 新局</span></span></code></pre></div><p><strong>超神与接气</strong></p><blockquote><p>超神接气要精通，移步换形在其中。 —— 《烟波钓叟歌》</p></blockquote><p>这是奇门时间推算的核心难点：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>理想状态：</span></span>
<span class="line"><span>  节气交节时刻 与 元的起点 完全对齐</span></span>
<span class="line"><span></span></span>
<span class="line"><span>现实情况：</span></span>
<span class="line"><span>  两者往往错位，产生两种情况：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  超神：</span></span>
<span class="line"><span>    按周期该换元了，但节气还未到</span></span>
<span class="line"><span>    → 提前启用下一节气的局</span></span>
<span class="line"><span>    → &quot;超前于节气&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  接气：</span></span>
<span class="line"><span>    节气已过，但按周期元尚未换</span></span>
<span class="line"><span>    → 继续沿用，等待新气接入</span></span>
<span class="line"><span>    → &quot;衔接新节气&quot;</span></span></code></pre></div><blockquote><p>超神接气的处理，是区分奇门遁甲<strong>入门排盘</strong>与<strong>精深推算</strong>的重要分水岭，本篇仅作概念说明，详细推算规则见奇门专篇。</p></blockquote><h4 id="奇门与农历的关系" tabindex="-1">奇门与农历的关系 <a class="header-anchor" href="#奇门与农历的关系" aria-label="Permalink to &quot;奇门与农历的关系&quot;">​</a></h4><p>奇门遁甲完全不使用农历月，它的时间坐标系是纯粹的节气太阳历，是二十四节气在术数中应用最精细的体系。</p><h3 id="_7-3-六爻-月建用节气-但有争议" tabindex="-1">7.3 六爻：月建用节气，但有争议 <a class="header-anchor" href="#_7-3-六爻-月建用节气-但有争议" aria-label="Permalink to &quot;7.3 六爻：月建用节气，但有争议&quot;">​</a></h3><p><strong>六爻的月建：</strong></p><p>六爻中，月建（当月地支）影响爻的旺衰，这是六爻断卦的重要参数。</p><p><strong>主流观点：月建以节气为准</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>与四柱相同：</span></span>
<span class="line"><span>过了节 → 换月建</span></span>
<span class="line"><span>未过节 → 用上月月建</span></span></code></pre></div><p><strong>争议观点：月建以农历朔日为准</strong></p><p>部分六爻传统认为，月建应以农历初一（朔日）为换月时刻，而非节气交节时刻。</p><p><strong>如实呈现：</strong><br> 这个争议在六爻传统中确实存在，不同门派有不同实践。</p><blockquote><p>本文采用主流观点（节气换月），但学习者应了解争议的存在，在实践中根据所学门派的规范操作。</p></blockquote><h3 id="_7-4-择日-阴阳合历并用" tabindex="-1">7.4 择日：阴阳合历并用 <a class="header-anchor" href="#_7-4-择日-阴阳合历并用" aria-label="Permalink to &quot;7.4 择日：阴阳合历并用&quot;">​</a></h3><p>择日是历法应用最综合的术数体系，同时使用农历（阴历轨道）和节气（阳历轨道）：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阴历轨道（朔望月）：</span></span>
<span class="line"><span>  → 农历日期（初一·十五·月相）</span></span>
<span class="line"><span>  → 建除十二神（以月建为基准起算）</span></span>
<span class="line"><span>  → 月破日（月建对冲之日）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阳历轨道（节气）：</span></span>
<span class="line"><span>  → 月建（换月以节气为准）</span></span>
<span class="line"><span>  → 节气日本身（某些节气日有特定宜忌）</span></span>
<span class="line"><span>  → 三伏·三九（以节气计算）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>干支轨道（两者叠加）：</span></span>
<span class="line"><span>  → 年·月·日·时的干支</span></span>
<span class="line"><span>  → 神煞（太岁·岁破·天德·月德等）</span></span></code></pre></div><p><strong>择日的历法复杂性：</strong><br> 正因为择日同时使用三套轨道，它是对历法知识要求最高的术数应用，也是最能体现阴阳合历精妙之处的实践领域。</p><h3 id="_7-5-大六壬-月将以节气换将" tabindex="-1">7.5 大六壬：月将以节气换将 <a class="header-anchor" href="#_7-5-大六壬-月将以节气换将" aria-label="Permalink to &quot;7.5 大六壬：月将以节气换将&quot;">​</a></h3><p><strong>大六壬的月将：</strong></p><p>大六壬用&quot;月将&quot;（太阳所在的黄道宫位）作为起课的时间参数。</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>月将换将时间：以节气中的&quot;气&quot;（中气）为准</span></span>
<span class="line"><span></span></span>
<span class="line"><span>具体对应：</span></span>
<span class="line"><span>雨水后  → 亥将（登明）</span></span>
<span class="line"><span>春分后  → 戌将（河魁）</span></span>
<span class="line"><span>谷雨后  → 酉将（从魁）</span></span>
<span class="line"><span>小满后  → 申将（传送）</span></span>
<span class="line"><span>夏至后  → 未将（小吉）</span></span>
<span class="line"><span>大暑后  → 午将（胜光）</span></span>
<span class="line"><span>处暑后  → 巳将（太乙）</span></span>
<span class="line"><span>秋分后  → 辰将（天罡）</span></span>
<span class="line"><span>霜降后  → 卯将（太冲）</span></span>
<span class="line"><span>小雪后  → 寅将（功曹）</span></span>
<span class="line"><span>冬至后  → 丑将（大吉）</span></span>
<span class="line"><span>大寒后  → 子将（神后）</span></span></code></pre></div><p><strong>注意：大六壬以&quot;气&quot;换将，四柱以&quot;节&quot;换月</strong><br> 这是两套体系在节气应用上的重要区别，不可混淆。</p><h3 id="_7-6-各术数历法基准总览" tabindex="-1">7.6 各术数历法基准总览 <a class="header-anchor" href="#_7-6-各术数历法基准总览" aria-label="Permalink to &quot;7.6 各术数历法基准总览&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">术数体系</th><th style="text-align:left;">换月/换年基准</th><th style="text-align:left;">使用的历法轨道</th><th style="text-align:left;">备注</th></tr></thead><tbody><tr><td style="text-align:left;">四柱八字</td><td style="text-align:left;">十二节（节气）</td><td style="text-align:left;">纯太阳历</td><td style="text-align:left;">年以立春换年</td></tr><tr><td style="text-align:left;">奇门遁甲</td><td style="text-align:left;">节气（节+气）</td><td style="text-align:left;">纯太阳历</td><td style="text-align:left;">精细到三元五天</td></tr><tr><td style="text-align:left;">六爻</td><td style="text-align:left;">节气（主流）</td><td style="text-align:left;">太阳历为主</td><td style="text-align:left;">存在朔日换月的争议</td></tr><tr><td style="text-align:left;">大六壬</td><td style="text-align:left;">十二气（中气）</td><td style="text-align:left;">太阳历</td><td style="text-align:left;">以气换将，非以节</td></tr><tr><td style="text-align:left;">择日</td><td style="text-align:left;">节气+朔日</td><td style="text-align:left;">阴阳合历并用</td><td style="text-align:left;">最综合</td></tr><tr><td style="text-align:left;">紫微斗数</td><td style="text-align:left;">农历月</td><td style="text-align:left;">阴历为主</td><td style="text-align:left;">与四柱不同</td></tr><tr><td style="text-align:left;">风水</td><td style="text-align:left;">节气+方位</td><td style="text-align:left;">太阳历为主</td><td style="text-align:left;">三元九运以甲子计</td></tr></tbody></table><blockquote><p><strong>一个值得深思的规律：</strong><br> 越是以&quot;天（太阳）&quot;为核心的术数，越用节气历；<br> 越是以&quot;人事·流年&quot;为核心的术数，越用农历月。<br> 这不是偶然，而是各体系对&quot;时间本质&quot;理解的不同侧重。</p></blockquote><h2 id="八、历法的文化层-从制度到生活" tabindex="-1">八、历法的文化层：从制度到生活 <a class="header-anchor" href="#八、历法的文化层-从制度到生活" aria-label="Permalink to &quot;八、历法的文化层：从制度到生活&quot;">​</a></h2><h3 id="_8-1-授时-天子的权力" tabindex="-1">8.1 授时：天子的权力 <a class="header-anchor" href="#_8-1-授时-天子的权力" aria-label="Permalink to &quot;8.1 授时：天子的权力&quot;">​</a></h3><p>在古代中国，<strong>颁布历法是天子的专属权力</strong>，称为&quot;颁朔&quot;或&quot;授时&quot;。</p><blockquote><p>历象日月星辰，敬授人时。 ——《尚书·尧典》</p></blockquote><p>《礼记·月令》记载：每月天子要&quot;告朔&quot;，即在太庙祭祀，宣布本月朔日，颁布本月的政令与禁忌。</p><p><strong>历法与政治合法性：</strong></p><ul><li>改朝换代必须&quot;改正朔&quot;（改变历法岁首）</li><li>藩属国使用宗主国历法，是臣服的象征</li><li>私自制历、私藏历书，在某些朝代是重罪</li></ul><p>这解释了为什么中国历史上有那么多套历法——每个朝代都需要通过改历来宣示&quot;奉天承运&quot;。</p><h3 id="_8-2-年节-历法活在节日里" tabindex="-1">8.2 年节：历法活在节日里 <a class="header-anchor" href="#_8-2-年节-历法活在节日里" aria-label="Permalink to &quot;8.2 年节：历法活在节日里&quot;">​</a></h3><p>中国传统节日，几乎全部建立在历法基础上：</p><table tabindex="0"><thead><tr><th style="text-align:left;">节日</th><th style="text-align:left;">历法基准</th><th style="text-align:left;">日期</th></tr></thead><tbody><tr><td style="text-align:left;">春节</td><td style="text-align:left;">农历正月初一（朔日）</td><td style="text-align:left;">朔望月</td></tr><tr><td style="text-align:left;">元宵节</td><td style="text-align:left;">农历正月十五（望日）</td><td style="text-align:left;">朔望月</td></tr><tr><td style="text-align:left;">清明节</td><td style="text-align:left;">清明节气</td><td style="text-align:left;">节气（太阳历）</td></tr><tr><td style="text-align:left;">端午节</td><td style="text-align:left;">农历五月初五</td><td style="text-align:left;">朔望月</td></tr><tr><td style="text-align:left;">七夕</td><td style="text-align:left;">农历七月初七</td><td style="text-align:left;">朔望月</td></tr><tr><td style="text-align:left;">中秋节</td><td style="text-align:left;">农历八月十五（望日）</td><td style="text-align:left;">朔望月</td></tr><tr><td style="text-align:left;">重阳节</td><td style="text-align:left;">农历九月初九</td><td style="text-align:left;">朔望月</td></tr><tr><td style="text-align:left;">冬至</td><td style="text-align:left;">冬至节气</td><td style="text-align:left;">节气（太阳历）</td></tr><tr><td style="text-align:left;">除夕</td><td style="text-align:left;">农历十二月最后一天</td><td style="text-align:left;">朔望月</td></tr></tbody></table><p><strong>有趣的规律：</strong></p><ul><li>以&quot;月相&quot;为核心的节日（元宵·中秋），用农历（朔望月）</li><li>以&quot;季节&quot;为核心的节日（清明·冬至），用节气（太阳历）</li><li>这正是阴阳合历&quot;双轨并行&quot;在节日文化中的体现</li></ul><h3 id="_8-3-三伏与三九-节气的延伸计算" tabindex="-1">8.3 三伏与三九：节气的延伸计算 <a class="header-anchor" href="#_8-3-三伏与三九-节气的延伸计算" aria-label="Permalink to &quot;8.3 三伏与三九：节气的延伸计算&quot;">​</a></h3><p><strong>三伏（最热）：</strong></p><p>入伏规则：</p><ul><li>夏至后第三个&quot;庚日&quot; = 初伏（10天）</li><li>夏至后第四个&quot;庚日&quot; = 中伏（10或20天）</li><li>立秋后第一个&quot;庚日&quot; = 末伏（10天）</li></ul><p><strong>为什么用&quot;庚日&quot;？</strong></p><p>庚属金，金畏火克，夏季火旺，庚金最受克制，故以庚日标记最热时段。这是干支五行与节气历法的交叉应用</p><p><strong>三九（最冷）：</strong></p><p>入九规则：</p><ul><li>冬至后每9天为一&quot;九&quot;</li><li>一九·二九·三九·……·九九</li><li>三九 = 冬至后第19-27天，是一年中最冷的时段</li></ul><p><strong>&quot;九九消寒图&quot;：从冬至开始，每天填一笔，填满81笔（九九八十一天），春天就到了。</strong></p><p>三伏三九，是节气历法与干支五行结合的典型应用，也是历法&quot;活在日常生活&quot;的最生动例证。</p><h3 id="_8-4-历法与中医-时间即治疗" tabindex="-1">8.4 历法与中医：时间即治疗 <a class="header-anchor" href="#_8-4-历法与中医-时间即治疗" aria-label="Permalink to &quot;8.4 历法与中医：时间即治疗&quot;">​</a></h3><p>《黄帝内经·素问·四气调神大论》：</p><blockquote><p>春三月，此谓发陈，天地俱生，万物以荣……<br> 夏三月，此谓蕃秀，天地气交，万物华实……<br> 秋三月，此谓容平，天气以急，地气以明……<br> 冬三月，此谓闭藏，水冰地坼，无扰乎阳……</p></blockquote><p>中医以历法（节气+月建）为时间坐标，指导养生、用药、针灸的时机：</p><ul><li>节气灸：在特定节气施灸，预防性治疗</li><li>冬至灸 → 补阳气，防寒症</li><li>夏至灸 → 清热，防暑症</li><li>三伏灸 → &quot;冬病夏治&quot;的核心时机</li><li>三九灸 → &quot;夏病冬治&quot;的核心时机</li></ul><h4 id="子午流注" tabindex="-1">子午流注 <a class="header-anchor" href="#子午流注" aria-label="Permalink to &quot;子午流注&quot;">​</a></h4><p>以十二时辰对应十二经络，按时辰选穴针灸。这是时辰历法与人体经络的对应</p><h4 id="五运六气" tabindex="-1">五运六气 <a class="header-anchor" href="#五运六气" aria-label="Permalink to &quot;五运六气&quot;">​</a></h4><p>以干支纪年推算每年的气候特征，指导当年的疾病预防与治疗。这是历法与医学的最深层结合</p><h2 id="九、万年历——历法的载体与工具" tabindex="-1">九、万年历——历法的载体与工具 <a class="header-anchor" href="#九、万年历——历法的载体与工具" aria-label="Permalink to &quot;九、万年历——历法的载体与工具&quot;">​</a></h2><h3 id="_9-1-万年历不是一种历法" tabindex="-1">9.1 万年历不是一种历法 <a class="header-anchor" href="#_9-1-万年历不是一种历法" aria-label="Permalink to &quot;9.1 万年历不是一种历法&quot;">​</a></h3><p>先说结论：</p><blockquote><p>**万年历不是独立的历法，<br> **<strong>而是把现有历法预先推算汇编的工具。</strong></p></blockquote><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>阴历（朔望月）  ┐</span></span>
<span class="line"><span>阳历（回归年）  ├─→ 预先计算 → 汇编 → 万年历</span></span>
<span class="line"><span>干支历（节气）  ┘</span></span>
<span class="line"><span></span></span>
<span class="line"><span>历法  = 数学规则（公式）</span></span>
<span class="line"><span>万年历 = 用规则提前算好的答案表</span></span></code></pre></div><p>打个比方：<br> 万年历之于历法，<br> 就像九九乘法表之于乘法——<br><strong>规则没变，只是把常用结果提前列出，不用每次现算。</strong></p><h3 id="_9-2-万年-是什么意思" tabindex="-1">9.2 &quot;万年&quot;是什么意思？ <a class="header-anchor" href="#_9-2-万年-是什么意思" aria-label="Permalink to &quot;9.2 &quot;万年&quot;是什么意思？&quot;">​</a></h3><p>不是真的推算了一万年。</p><ul><li>古代版：通常推算 60年（一个甲子）或 100</li><li>现代纸质版：通常推算 100-200年</li><li>数字App版：理论上可以无限推算（用现代天文算法）</li></ul><p>&quot;万年&quot;是<strong>夸张修辞</strong>，与&quot;万寿无疆&quot;&quot;万古长青&quot;用法相同，意思是&quot;长久可用、永久有效&quot;，不是字面意义上的一万年。</p><h3 id="_9-3-万年历的历史来源" tabindex="-1">9.3 万年历的历史来源 <a class="header-anchor" href="#_9-3-万年历的历史来源" aria-label="Permalink to &quot;9.3 万年历的历史来源&quot;">​</a></h3><p><strong>起源于历代官方颁历的实际需要：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>古代运作逻辑：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>钦天监（国家天文机构）</span></span>
<span class="line"><span>    ↓ 每年推算来年历书</span></span>
<span class="line"><span>颁布给全国使用（&quot;颁朔&quot;）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>问题：</span></span>
<span class="line"><span>皇帝·官员需要提前规划数年，</span></span>
<span class="line"><span>希望能查到未来多年的日期·节气·吉凶</span></span>
<span class="line"><span></span></span>
<span class="line"><span>→ 出现了提前推算多年的&quot;长历&quot;</span></span>
<span class="line"><span>→ 民间需求扩大</span></span>
<span class="line"><span>→ 明清：民间历书（皇历/通书）大量流行</span></span>
<span class="line"><span>→ &quot;万年历&quot;名称逐渐固定</span></span></code></pre></div><p><strong>历史沿革简表：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">时期</th><th style="text-align:left;">形态</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;">汉代以前</td><td style="text-align:left;">官方颁历</td><td style="text-align:left;">每年颁布，仅含当年</td></tr><tr><td style="text-align:left;">唐宋</td><td style="text-align:left;">长历·具注历</td><td style="text-align:left;">含多年日期+节气+宜忌</td></tr><tr><td style="text-align:left;">明清</td><td style="text-align:left;">皇历·通书</td><td style="text-align:left;">民间广泛流通，含干支·神煞·宜忌</td></tr><tr><td style="text-align:left;">近现代</td><td style="text-align:left;">印刷万年历</td><td style="text-align:left;">通常含100年，案头工具书</td></tr><tr><td style="text-align:left;">当代</td><td style="text-align:left;">万年历App</td><td style="text-align:left;">实时计算，理论上无限年</td></tr></tbody></table><hr><h3 id="_9-4-万年历包含什么-——三套历法的叠加显示" tabindex="-1">9.4 万年历包含什么？——三套历法的叠加显示 <a class="header-anchor" href="#_9-4-万年历包含什么-——三套历法的叠加显示" aria-label="Permalink to &quot;9.4 万年历包含什么？——三套历法的叠加显示&quot;">​</a></h3><p>现代万年历（无论纸质还是App），<br> 本质上是一个<strong>多历法对照查询工具</strong>，<br> 同一天同时显示三套历法的信息：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>同一天，万年历显示：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>┌───────────────────────────────┐</span></span>
<span class="line"><span>│  公历：2026年7月23日（星期四）    │  ← 格里历（纯太阳历）</span></span>
<span class="line"><span>│  农历：六月初九                  │  ← 阴阳合历（朔望月）</span></span>
<span class="line"><span>│  干支：丙午年·壬午月·庚午日       │  ← 干支历（节气历）</span></span>
<span class="line"><span>│  节气：大暑（7月23日）           │  ← 太阳黄经120°</span></span>
<span class="line"><span>│  宜：祭祀·出行                  │  ← 择日术数系统</span></span>
<span class="line"><span>│  忌：动土·嫁娶                  │  ← 择日术数系统</span></span>
<span class="line"><span>└───────────────────────────────┘</span></span></code></pre></div><p>**它把三套历法的计算结果叠加在同一天上显示，<br> **<strong>本身不是第四种历法。</strong></p><h3 id="_9-5-一个常见误解的澄清" tabindex="-1">9.5 一个常见误解的澄清 <a class="header-anchor" href="#_9-5-一个常见误解的澄清" aria-label="Permalink to &quot;9.5 一个常见误解的澄清&quot;">​</a></h3><blockquote><p>❌ 很多人以为：&quot;农历 = 阴历 = 万年历上的那套&quot;</p></blockquote><p>实际上，万年历上同时有三套：</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>公历   → 太阳历（与月相无关）</span></span>
<span class="line"><span>农历   → 阴阳合历（不是纯阴历）</span></span>
<span class="line"><span>干支历 → 纯太阳历（节气换月，与农历月无关）</span></span></code></pre></div><p>三套并列显示，万年历只是容器，<br> 不代表它们是同一种历法。</p><blockquote><p>这也是为什么：<br> 同一天，农历是&quot;六月初九&quot;，<br> 干支月却可能已经是&quot;壬午月&quot;（芒种后）——<br> 两套历法的月份换月基准根本不同，<br> 万年历把它们同时显示出来，<br> 反而容易造成混淆。</p><p><strong>使用万年历时，必须清楚自己在看哪一套。</strong><br> 四柱排盘看干支栏，不看农历栏</p></blockquote><h3 id="_9-6-万年历与术数实战" tabindex="-1">9.6 万年历与术数实战 <a class="header-anchor" href="#_9-6-万年历与术数实战" aria-label="Permalink to &quot;9.6 万年历与术数实战&quot;">​</a></h3><p>万年历在术数实践中的核心用途：</p><table tabindex="0"><thead><tr><th style="text-align:left;">用途</th><th style="text-align:left;">看哪一栏</th><th style="text-align:left;">注意事项</th></tr></thead><tbody><tr><td style="text-align:left;">四柱排盘（年月日时柱）</td><td style="text-align:left;"><strong>干支栏</strong></td><td style="text-align:left;">年以立春换年，月以节换月</td></tr><tr><td style="text-align:left;">奇门起局</td><td style="text-align:left;"><strong>节气时刻</strong></td><td style="text-align:left;">需精确到分钟的交节时刻</td></tr><tr><td style="text-align:left;">六爻月建</td><td style="text-align:left;"><strong>干支月</strong></td><td style="text-align:left;">以节气换月（主流）</td></tr><tr><td style="text-align:left;">择日</td><td style="text-align:left;"><strong>农历+干支+节气</strong> 三栏并用</td><td style="text-align:left;">最综合，三套都要看</td></tr><tr><td style="text-align:left;">大六壬月将</td><td style="text-align:left;"><strong>中气时刻</strong></td><td style="text-align:left;">以气换将，非以节</td></tr></tbody></table><p><strong>万年历的局限：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>纸质万年历：</span></span>
<span class="line"><span>  → 节气时刻通常只精确到&quot;日&quot;，</span></span>
<span class="line"><span>    不标注具体时分</span></span>
<span class="line"><span>  → 四柱排盘时，节气当天出生者，</span></span>
<span class="line"><span>    必须另查精确交节时刻，不可只看万年历日期</span></span>
<span class="line"><span></span></span>
<span class="line"><span>App万年历：</span></span>
<span class="line"><span>  → 大多数App已提供精确交节时刻</span></span>
<span class="line"><span>  → 但宜忌·神煞的计算逻辑各家不同，</span></span>
<span class="line"><span>    仅供参考，不可盲从</span></span></code></pre></div><h3 id="_9-7-小结" tabindex="-1">9.7 小结 <a class="header-anchor" href="#_9-7-小结" aria-label="Permalink to &quot;9.7 小结&quot;">​</a></h3><h4 id="万年历的本质" tabindex="-1">万年历的本质： <a class="header-anchor" href="#万年历的本质" aria-label="Permalink to &quot;万年历的本质：&quot;">​</a></h4><ul><li>工具，不是历法</li><li>容器，不是内容</li><li>答案表，不是公式</li></ul><h4 id="万年历的价值" tabindex="-1">万年历的价值： <a class="header-anchor" href="#万年历的价值" aria-label="Permalink to &quot;万年历的价值：&quot;">​</a></h4><p>把公历·农历·干支历三套历法的计算结果，汇聚在同一个界面，方便日常查阅。</p><p><strong>一句话：</strong><br> 万年历是历法知识的&quot;显示屏&quot;，但读懂显示屏上的内容，<br> 需要先理解屏幕背后三套历法各自的逻辑。</p><h2 id="十、现代解读" tabindex="-1">十、现代解读 <a class="header-anchor" href="#十、现代解读" aria-label="Permalink to &quot;十、现代解读&quot;">​</a></h2><h3 id="_10-1-农历的现代科学地位" tabindex="-1">10.1 农历的现代科学地位 <a class="header-anchor" href="#_10-1-农历的现代科学地位" aria-label="Permalink to &quot;10.1 农历的现代科学地位&quot;">​</a></h3><p><strong>农历不是&quot;封建迷信&quot;，而是精确的天文历法系统：</strong></p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>现代天文学验证：</span></span>
<span class="line"><span>  朔日计算：现行农历用现代天文方法精确计算合朔时刻，</span></span>
<span class="line"><span>            误差在秒级以内</span></span>
<span class="line"><span>  节气计算：用现代天文软件计算节气时刻，</span></span>
<span class="line"><span>            与古代历法的误差在分钟级别</span></span>
<span class="line"><span>  19年7闰：现代天文学完全验证了默冬周期的精确性</span></span></code></pre></div><p><strong>农历在现代的实用价值：</strong></p><table tabindex="0"><thead><tr><th style="text-align:left;">领域</th><th style="text-align:left;">农历的现代应用</th></tr></thead><tbody><tr><td style="text-align:left;">农业</td><td style="text-align:left;">节气指导播种收割，沿用至今</td></tr><tr><td style="text-align:left;">渔业</td><td style="text-align:left;">朔望月指导潮汐预测，渔民仍用农历</td></tr><tr><td style="text-align:left;">中医</td><td style="text-align:left;">节气灸·子午流注·五运六气</td></tr><tr><td style="text-align:left;">民俗</td><td style="text-align:left;">传统节日·婚丧嫁娶择日</td></tr><tr><td style="text-align:left;">天文</td><td style="text-align:left;">月食·日食预测（朔望月）</td></tr></tbody></table><hr><h3 id="_10-2-公历-vs-农历-不是替代-是互补" tabindex="-1">10.2 公历 vs 农历：不是替代，是互补 <a class="header-anchor" href="#_10-2-公历-vs-农历-不是替代-是互补" aria-label="Permalink to &quot;10.2 公历 vs 农历：不是替代，是互补&quot;">​</a></h3><p>常见误解：公历是&quot;科学的&quot;，农历是&quot;<strong>落后</strong>的&quot;</p><p>正确理解：</p><ul><li>公历（格里历）= 纯太阳历，<strong>适合国际通用、工业计时</strong></li><li>农历（阴阳合历）= <strong>阴阳合历，适合农业、渔业、中医、民俗</strong></li></ul><p>两者不是竞争关系，而是服务于不同需求的两套系统。</p><p>中国现代社会同时使用两套历法，这本身就是一种文化智慧：</p><p>用公历处理国际事务，用农历传承文化传统。</p><h3 id="_10-3-历法思维-时间是有质地的" tabindex="-1">10.3 历法思维：时间是有质地的 <a class="header-anchor" href="#_10-3-历法思维-时间是有质地的" aria-label="Permalink to &quot;10.3 历法思维：时间是有质地的&quot;">​</a></h3><p>公历思维：时间是均匀的刻度，1月1日和7月1日没有本质区别。</p><p>历法思维（节气+月建）：时间是有质地的——</p><div class="language-plain vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plain</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>寅月的时间，是木气初生、万物萌动的时间；</span></span>
<span class="line"><span>午月的时间，是火气帝旺、阳极将转的时间；</span></span>
<span class="line"><span>子月的时间，是水气最旺、一阳初生的时间。</span></span>
<span class="line"><span></span></span>
<span class="line"><span>同样是&quot;一个月&quot;，</span></span>
<span class="line"><span>寅月和子月的能量质地完全不同，</span></span>
<span class="line"><span>适合做的事、需要注意的方向，也完全不同。</span></span></code></pre></div><p>这不是迷信，而是一种<strong>与自然节律同频的时间感知方式</strong>。<br> 它建立在真实的天文观测基础上，<br> 经过数千年的农业实践验证，<br> 是中华文明对时间本质的独特洞察。</p><hr><h2 id="十一、承前启后" tabindex="-1">十一、承前启后 <a class="header-anchor" href="#十一、承前启后" aria-label="Permalink to &quot;十一、承前启后&quot;">​</a></h2><p><strong>上承：</strong></p><ul><li>二十四节气（节气是农历的太阳骨架，本篇的前提）</li><li>十二地支（月建 = 地支月，历法与地支的接口）</li><li>六十甲子（干支纪年纪月纪日，历法的干支坐标）</li><li>阴阳论（阴阳合历 = 阴阳论在历法中的实践）</li></ul><p><strong>本篇建立：</strong></p><ul><li>三种历法的本质区别（纯阴历·纯阳历·阴阳合历）</li><li>农历的核心机制（朔望月·回归年·置闰法·月建）</li><li>节气在历法中的位置（阳骨架·无中气置闰）</li><li>各术数体系的历法接口（四柱·奇门·六爻·择日·六壬）</li></ul><p><strong>下启：</strong></p><ul><li>→ 16·十二长生（月建与五行旺衰的精细化，建立在月建基础上）</li><li>→ 17·五行旺相休囚死（节气季节与五行能量的对应）</li><li>→ 奇门遁甲实战（节气历法是奇门起局的时间基准）</li><li>→ 择日实战（阴阳合历的综合应用）</li><li>→ 五运六气（历法与中医的最深层结合，待建）</li></ul><hr><h2 id="十二、本章小结" tabindex="-1">十二、本章小结 <a class="header-anchor" href="#十二、本章小结" aria-label="Permalink to &quot;十二、本章小结&quot;">​</a></h2><p>历法，是人类把天文周期转化为社会时间坐标的系统工程。<br> 中国农历，是这项工程中最复杂、也最精妙的成就之一。</p><p><strong>五个核心认知：</strong></p><p><strong>① 农历不是阴历</strong><br> 农历是阴阳合历，同时追踪太阳（节气）和月亮（朔望月），<br> 用置闰法协调两者。把农历叫做&quot;阴历&quot;，是一个根本性的误解。</p><p><strong>② 节气是农历的太阳骨架</strong><br> 节气属于太阳历，嵌入农历，构成农历的&quot;阳&quot;的部分。<br> 节气在公历中日期稳定，在农历中日期漂移，<br> 根本原因是两者的天文基准不同。</p><p><strong>③ 置闰法是阴阳合历的核心机制</strong><br> 19年7闰，无中气置闰——<br> 这套规则用太阳历（节气）来规范阴历（朔望月）的置闰，<br> 是&quot;以阳统阴&quot;的历法智慧。</p><p><strong>④ 不同术数用不同历法基准</strong><br> 四柱·奇门用节气历（纯太阳历），<br> 六爻月建以节气为主，<br> 择日阴阳合历并用，<br> 大六壬以中气换将。<br> 理解这个差异，是避免术数实战错误的基础。</p><p><strong>⑤ 历法思维：时间是有质地的</strong><br> 节气历法不只是计时工具，<br> 它是一种与自然节律同频的时间感知方式。<br> 每个月建都有其独特的能量质地，<br> 这是中华文明对时间本质的独特洞察，<br> 也是术数体系得以成立的时间哲学基础。</p><hr><p><strong>学历法，有两个层次：</strong></p><p>第一层：记住三种历法的区别，<br> 记住农历的核心机制（朔望月·置闰·月建），<br> 记住各术数体系用哪种历法基准。<br> 这是工具层，必须熟练。</p><p>第二层：理解为什么古人要建立这套系统——<br> 他们面对的问题是：太阳和月亮，各有自己的节律，<br> 两者不同步，但人的生活需要同时跟随两者。<br> 农历，是古人给出的答案：<br><strong>不放弃任何一个，用智慧让两者和谐共存。</strong></p><p>这种&quot;和而不同、阴阳并行&quot;的思维方式，<br> 不只是历法的逻辑，更是中华文化底层世界观的体现。</p><hr><p><strong>下一篇预告：</strong><br> 16 · 十二长生——生命周期的能量模型：<br> 长生·沐浴·冠带·临官·帝旺·衰·病·死·墓·绝·胎·养，<br> 十二个状态，描述五行能量从萌生到消亡的完整周期，<br> 是四柱·奇门·六爻共用的能量判断模型。</p><hr><p><em>文档版本：v1.0 · 历法体系 | 2026年7月 | 初稿完成</em></p><h2 id="补充材料" tabindex="-1">补充材料 <a class="header-anchor" href="#补充材料" aria-label="Permalink to &quot;补充材料&quot;">​</a></h2><ul><li><a href="/Dao/topics/traditional-wisdom/time/calendar-system/appendix">历法术语附录</a></li><li><a href="/Dao/topics/traditional-wisdom/time/calendar-system/source-notes">正本清源：十九年周期及其传播问题</a></li></ul>`,341)])])}const u=a(e,[["render",p]]);export{c as __pageData,u as default};
